import{_ as e,o as s,c as n,a3 as p}from"./chunks/framework.BZCmpA0A.js";const h=JSON.parse('{"title":"04 · 行程管理","description":"","frontmatter":{},"headers":[],"relativePath":"topics/processes.md","filePath":"topics/processes.md","lastUpdated":1793079736000}'),r={name:"topics/processes.md"};function l(i,a,c,t,o,d){return s(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="_04-·-行程管理" tabindex="-1">04 · 行程管理 <a class="header-anchor" href="#_04-·-行程管理" aria-label="Permalink to &quot;04 · 行程管理&quot;">​</a></h1><p>程式是一份指令與資料；Process（行程）是這份程式正在執行的一次實例。兩個行程可以執行同一份程式，卻擁有不同 PID、暫存器與私有資料。</p><h2 id="pcb-保存什麼" tabindex="-1">PCB 保存什麼 <a class="header-anchor" href="#pcb-保存什麼" aria-label="Permalink to &quot;PCB 保存什麼&quot;">​</a></h2><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/process.h" target="_blank" rel="noreferrer">kernel/process.h（GitHub）</a>。</p><p><code>ProcessControlBlock</code> 就是 PCB（行程控制區塊），<code>processes[4]</code> 是目前行程表。<code>page_table</code> 找到私有位址空間，<code>frame</code> 找到暫存器保存狀態；等待與 I/O 欄位記錄阻塞後還沒完成的事。</p><p><code>ready_next</code> 是指向下一個 Ready PCB 的指標，不是另一份行程副本。核心堆疊每欄固定 16 KiB；使用者頁面則由 VM 按需要配置。</p><h2 id="狀態怎麼走" tabindex="-1">狀態怎麼走 <a class="header-anchor" href="#狀態怎麼走" aria-label="Permalink to &quot;狀態怎麼走&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unused → New → Ready → Running</span></span>
<span class="line"><span>                 ↑        ├─ yield → Ready</span></span>
<span class="line"><span>                 │        ├─ sleep／wait／阻塞 I/O → Waiting</span></span>
<span class="line"><span>                 └─ 喚醒 ─┘</span></span>
<span class="line"><span>Running／Ready／Waiting → exit／kill → Zombie → wait → Unused</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Zombie（已退出、待回收）仍保留結束結果與資源，讓父行程能透過 wait 取得結果。它已不再執行，也不在 Ready queue（就緒佇列）裡。</p><h2 id="建立、複製與替換" tabindex="-1">建立、複製與替換 <a class="header-anchor" href="#建立、複製與替換" aria-label="Permalink to &quot;建立、複製與替換&quot;">​</a></h2><p><code>create_process</code> 取得空 PCB，準備頁表與初始 TrapFrame，成功後才公布 Ready。建立中途失敗就回收不完整空間。</p><p><code>process_fork</code> 複製父行程的使用者內容與已越過 ecall 的暫存器狀態。父 a0 得到子 PID，子 a0 得到 0。核心堆疊不直接複製；常駐頁與已交換資料都取得獨立內容，目前沒有 COW（寫入時複製）。</p><p><code>process_exec</code> 先準備新空間與必要參數，成功後才切換並銷毀舊空間。PID 和父子關係保留，下一次返回使用者模式時從新程式入口開始。</p><h2 id="在-qemu-觀察" tabindex="-1">在 QEMU 觀察 <a class="header-anchor" href="#在-qemu-觀察" aria-label="Permalink to &quot;在 QEMU 觀察&quot;">​</a></h2><p>從新開機開始，逐條輸入：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fork</span></span>
<span class="line"><span>ps</span></span>
<span class="line"><span>wait 2</span></span>
<span class="line"><span>run worker</span></span>
<span class="line"><span>ps</span></span>
<span class="line"><span>pcb 3</span></span>
<span class="line"><span>wakeup 7</span></span>
<span class="line"><span>wait 3</span></span>
<span class="line"><span>ps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>父子應顯示不同的私有 data／stack 值。worker 等待事件通道 7，喚醒後可回收。若先前已建立過行程，請以實際輸出的 PID 取代 2／3；<code>sleep(7)</code> 是等待通道 7，不是睡 7 秒。</p><h2 id="回收與限制" tabindex="-1">回收與限制 <a class="header-anchor" href="#回收與限制" aria-label="Permalink to &quot;回收與限制&quot;">​</a></h2><p>exit 關閉端點並留下 Zombie；wait 取得結果後釋放使用者頁、Swap slots（交換區槽位）、私有頁表及 PCB。孤兒行程另有接管與回收流程。狀態結果寫入父使用者空間失敗時，不會先丟棄 Zombie。</p><p>最多 4 個行程，exec 仍只選擇核心內嵌的程式 ID，不是載入任意磁碟執行檔。沒有執行緒與完整作業控制。</p><p>觀念參考：<code>notes/ch3 Process.md</code>。實作脈絡見 <a href="./../SPEC-02-process-lifecycle.html">Spec 02</a>、<a href="./../SPEC.html">Spec 05</a>，目前私有記憶體複製見 <a href="./../SPEC-10-demand-paging.html">Spec 10</a>。</p>`,21)])])}const u=e(r,[["render",l]]);export{h as __pageData,u as default};
